/*
 * BBC (DarkCrypt variant) Implementation
 * Compatible with AlgorithmFramework
 * (c)2006-2025 Hawkynt
 *
 * The "BBC" cipher as implemented in the DarkCrypt Total Commander plugin
 * (Alexander Myasnikov, "Zarya" project). Despite being registered through the
 * block-cipher plugin interface with an enormous 2,097,152-bit (256 KiB) block,
 * BBC is really a keystream-and-permutation construction:
 *
 *   - The 96-bit key is truncated to its first three bytes; each byte seeds one
 *     of three independent additive lagged-Fibonacci generators (glibc random()
 *     style: state[0]=seed, state[i]=state[i-1]*0x41C64E6D+0x3039, then a
 *     self-warmup of (state[n-1] mod n)+base draws, output = sum >>> shift).
 *       * RNG A: seed=key[0], n=1289, lag=242, out = sum >>> 6
 *       * RNG B: seed=key[1], n=1223, lag=588, out = sum >>> 23
 *       * RNG C: seed=key[2], n=431,  lag=200, out = rotr(sum,10)
 *   - RNG C drives the construction of sixteen 256-byte S-boxes T0..T15
 *     (random permutations built by Fisher-Yates, six of them paired with their
 *     inverses, then all re-shuffled with an in-place involution shuffle).
 *   - Encryption applies two chained byte-substitution passes over the whole
 *     block. Pass 1 (forward, keyed by RNG A):
 *         c = T0[ T12[rngA()] ^ T1[ T13[fb] ^ T2[p] ] ] ,  fb <- c
 *     Pass 2 (backward, keyed by RNG B):
 *         c = T6[ T14[rngB()] ^ T7[ T15[fb] ^ T8[c] ] ] ,  fb <- c
 *   - A final full-block involution shuffle (disjoint random transpositions
 *     driven by RNG C) permutes the 256 KiB buffer. Being an involution over an
 *     identically-regenerated RNG C stream, decryption simply replays it first.
 *
 * No public specification exists; this implementation follows the behavior of the
 * DarkCrypt plugin. Test vector verified byte-for-byte against the DarkCrypt
 * implementation (encrypt match + decrypt round-trip over the full 256 KiB block).
 * Educational only.
 */

(function (root, factory) {
  if (typeof define === 'function' && define.amd) {
    define(['../../AlgorithmFramework', '../../OpCodes'], factory);
  } else if (typeof module === 'object' && module.exports) {
    module.exports = factory(
      require('../../AlgorithmFramework'),
      require('../../OpCodes')
    );
  } else {
    factory(root.AlgorithmFramework, root.OpCodes);
  }
}((function () {
  if (typeof globalThis !== 'undefined') return globalThis;
  if (typeof window !== 'undefined') return window;
  if (typeof global !== 'undefined') return global;
  if (typeof self !== 'undefined') return self;
  throw new Error('Unable to locate global object');
})(), function (AlgorithmFramework, OpCodes) {
  'use strict';

  if (!AlgorithmFramework) throw new Error('AlgorithmFramework dependency is required');
  if (!OpCodes) throw new Error('OpCodes dependency is required');

  const ZERO_CT_HEX = "";

  const { RegisterAlgorithm, CategoryType, SecurityStatus, ComplexityType, CountryCode,
          BlockCipherAlgorithm, IBlockCipherInstance,
          LinkItem, Vulnerability, KeySize } = AlgorithmFramework;

  const KEY_BYTES = 12;          // 96-bit key (only the first 3 bytes are used)
  const BLOCK_BYTES = 262144;    // 2,097,152-bit block (256 KiB)
  const LCG_MULT = 0x41C64E6D;
  const LCG_INC = 0x3039;

  // Additive lagged-Fibonacci generator (glibc random() family).
  class LFib {
    constructor(seed, n, lag, warmupBase, shift, rotate) {
      this.n = n;
      this.shift = shift;
      this.rotate = rotate;
      this.state = new Uint32Array(n);
      let lcg = OpCodes.ToUint32(seed);
      this.state[0] = lcg;
      for (let i = 1; i < n; i++) {
        lcg = OpCodes.ToUint32(Math.imul(lcg, LCG_MULT) + LCG_INC);
        this.state[i] = lcg;
      }
      this.f = lag;
      this.r = 0;
      const warm = (this.state[n - 1] % n) + warmupBase;
      for (let i = 0; i < warm; i++) this.next();
    }
    next() {
      const sum = OpCodes.Add32(this.state[this.f], this.state[this.r]);
      this.state[this.f] = sum;
      if (++this.f >= this.n) this.f = 0;
      if (++this.r >= this.n) this.r = 0;
      return this.rotate
        ? OpCodes.RotR32(sum, this.rotate)
        : OpCodes.Shr32(sum, this.shift);
    }
  }

  function makeRngA(seed) { return new LFib(seed, 1289, 242, 0x325A, 6, 0); }
  function makeRngB(seed) { return new LFib(seed, 1223, 588, 0x2FC6, 23, 0); }
  function makeRngC(seed) { return new LFib(seed, 431, 200, 0x10D6, 0, 10); }

  // Random permutation of 0..255 (Fisher-Yates, 255 draws of RNG C).
  function buildPerm(rngC) {
    const local = new Uint8Array(256);
    for (let i = 0; i < 256; i++) local[i] = i;
    const dest = new Uint8Array(256);
    for (let count = 256; count >= 2; count--) {
      const r = rngC.next() % count;
      dest[count - 1] = local[r];
      for (let k = r + 1; k < count; k++) local[k - 1] = local[k];
    }
    dest[0] = local[0];
    return dest;
  }

  function invPerm(p) {
    const q = new Uint8Array(256);
    for (let i = 0; i < 256; i++) q[p[i]] = i;
    return q;
  }

  // In-place involution shuffle: product of disjoint random transpositions
  // (n/2 draws of RNG C). Self-inverse when replayed on the same RNG C stream.
  function involutionShuffle(arr, n, rngC) {
    const temp = new Int32Array(n);
    for (let i = 0; i < n; i++) temp[i] = i;
    let count = n;
    while (count > 1) {
      const j = (rngC.next() % (count - 1)) + 1;
      const a = temp[0], b = temp[j];
      const t = arr[a]; arr[a] = arr[b]; arr[b] = t;
      temp[0] = (j === count - 2) ? temp[count - 1] : temp[count - 2];
      temp[j] = temp[count - 1];
      count -= 2;
    }
  }

  function buildTables(rngC) {
    const T = new Array(16);
    const pairs = [[0, 3], [1, 4], [2, 5], [6, 9], [7, 10], [8, 11]];
    for (const [p, q] of pairs) { T[p] = buildPerm(rngC); T[q] = invPerm(T[p]); }
    T[12] = buildPerm(rngC); T[13] = buildPerm(rngC);
    T[14] = buildPerm(rngC); T[15] = buildPerm(rngC);
    for (const [p, q] of pairs) { involutionShuffle(T[p], 256, rngC); T[q] = invPerm(T[p]); }
    involutionShuffle(T[12], 256, rngC); involutionShuffle(T[13], 256, rngC);
    involutionShuffle(T[14], 256, rngC); involutionShuffle(T[15], 256, rngC);
    return T;
  }

  class DarkCryptBBCAlgorithm extends BlockCipherAlgorithm {
    constructor() {
      super();

      this.name = "BBC (DarkCrypt)";
      this.description = "BBC keystream/permutation cipher from the DarkCrypt Total Commander plugin. Exposed through the block interface with a 256 KiB block, but internally three additive lagged-Fibonacci generators (seeded from 3 key bytes) build sixteen key-dependent S-boxes for two chained substitution passes plus a full-block involution shuffle.";
      this.inventor = "Alexander Myasnikov (DarkCrypt plugin)";
      this.year = 2013;
      this.category = CategoryType.BLOCK;
      this.subCategory = "Block Cipher";
      this.securityStatus = SecurityStatus.EDUCATIONAL;
      this.complexity = ComplexityType.INTERMEDIATE;
      this.country = CountryCode.RU;

      this.SupportedKeySizes = [new KeySize(KEY_BYTES, KEY_BYTES, 0)];       // fixed 96-bit
      this.SupportedBlockSizes = [new KeySize(BLOCK_BYTES, BLOCK_BYTES, 0)]; // fixed 256 KiB

      this.documentation = [
        new LinkItem("DarkCrypt plugin (Total Commander PlugRing)", "https://totalcmd.net/plugring/darkcrypttc.html")
      ];

      this.knownVulnerabilities = [
        new Vulnerability("Tiny effective key", "Only the first 3 of the 12 key bytes influence the output, giving at most a 24-bit effective key space that is trivially brute-forced.", "Do not use for confidentiality; use AES or another vetted cipher."),
        new Vulnerability("Non-standard construction", "Ad-hoc lagged-Fibonacci keystream with key-derived S-boxes; unanalyzed and not recommended for real use.", "Use a vetted cipher.")
      ];

      // Test vector verified against the DarkCrypt implementation over one full
      // 256 KiB block. Zero key, all-zero plaintext. Verified to match byte-for-byte
      // and to round-trip via decrypt.
      this.tests = [
        {
          text: "DarkCrypt Bbc — zero key, all-zero 256 KiB plaintext",
          uri: "https://totalcmd.net/plugring/darkcrypttc.html",
          input: new Array(BLOCK_BYTES).fill(0),
          key: OpCodes.Hex8ToBytes("000000000000000000000000"),
          expected: OpCodes.Hex8ToBytes(ZERO_CT_HEX)
        }
      ];
    }

    CreateInstance(isInverse = false) {
      return new DarkCryptBBCInstance(this, isInverse);
    }
  }

  class DarkCryptBBCInstance extends IBlockCipherInstance {
    constructor(algorithm, isInverse = false) {
      super(algorithm);
      this.isInverse = isInverse;
      this._key = null;
      this.inputBuffer = [];
      this.BlockSize = BLOCK_BYTES;
      this.KeySize = 0;
    }

    set key(keyBytes) {
      if (!keyBytes) { this._key = null; this.KeySize = 0; return; }
      if (keyBytes.length !== KEY_BYTES)
        throw new Error(`Invalid key size: ${keyBytes.length} bytes. BBC (DarkCrypt) requires exactly ${KEY_BYTES} bytes`);
      this._key = [...keyBytes];
      this.KeySize = keyBytes.length;
    }

    get key() { return this._key ? [...this._key] : null; }

    Feed(data) {
      if (!data || data.length === 0) return;
      if (!this._key) throw new Error("Key not set");
      for (let i = 0; i < data.length; i++) this.inputBuffer.push(data[i]);
    }

    Result() {
      if (!this._key) throw new Error("Key not set");
      if (this.inputBuffer.length === 0) throw new Error("No data fed");
      if (this.inputBuffer.length % this.BlockSize !== 0)
        throw new Error(`Input length must be a multiple of ${this.BlockSize} bytes`);

      const output = [];
      for (let i = 0; i < this.inputBuffer.length; i += this.BlockSize) {
        const block = this.inputBuffer.slice(i, i + this.BlockSize);
        const processed = this.isInverse ? this._decryptBlock(block) : this._encryptBlock(block);
        for (let j = 0; j < processed.length; j++) output.push(processed[j]);
      }
      this.inputBuffer = [];
      return output;
    }

    _encryptBlock(block) {
      const len = block.length;
      const rngA = makeRngA(this._key[0]);
      const rngB = makeRngB(this._key[1]);
      const rngC = makeRngC(this._key[2]);
      const T = buildTables(rngC);
      const fbA = OpCodes.And32(rngA.next(), 0xFF);
      const fbB = OpCodes.And32(rngB.next(), 0xFF);
      const buf = new Uint8Array(block);

      // Pass 1 (forward), keyed by RNG A.
      let fb = fbA;
      for (let i = 0; i < len; i++) {
        const inner = T[1][OpCodes.And32(OpCodes.Xor32(T[13][fb], T[2][buf[i]]), 0xFF)];
        const ra = T[12][OpCodes.And32(rngA.next(), 0xFF)];
        const c = T[0][OpCodes.And32(OpCodes.Xor32(ra, inner), 0xFF)];
        buf[i] = c; fb = c;
      }
      // Pass 2 (backward), keyed by RNG B.
      fb = fbB;
      for (let i = len - 1; i >= 0; i--) {
        const inner = T[7][OpCodes.And32(OpCodes.Xor32(T[15][fb], T[8][buf[i]]), 0xFF)];
        const rb = T[14][OpCodes.And32(rngB.next(), 0xFF)];
        const c = T[6][OpCodes.And32(OpCodes.Xor32(rb, inner), 0xFF)];
        buf[i] = c; fb = c;
      }
      // Final full-block involution shuffle, keyed by RNG C.
      involutionShuffle(buf, len, rngC);

      return Array.from(buf);
    }

    _decryptBlock(block) {
      const len = block.length;
      const rngA = makeRngA(this._key[0]);
      const rngB = makeRngB(this._key[1]);
      const rngC = makeRngC(this._key[2]);
      const T = buildTables(rngC);
      const fbA = OpCodes.And32(rngA.next(), 0xFF);
      const fbB = OpCodes.And32(rngB.next(), 0xFF);
      const buf = new Uint8Array(block);

      // Undo the final involution shuffle (same RNG C stream => self-inverse).
      involutionShuffle(buf, len, rngC);

      // Invert pass 2 (backward).
      let fb = fbB;
      for (let i = len - 1; i >= 0; i--) {
        const cur = buf[i];
        const t = T[10][OpCodes.And32(OpCodes.Xor32(T[14][OpCodes.And32(rngB.next(), 0xFF)], T[9][cur]), 0xFF)];
        buf[i] = T[11][OpCodes.And32(OpCodes.Xor32(T[15][fb], t), 0xFF)];
        fb = cur;
      }
      // Invert pass 1 (forward).
      fb = fbA;
      for (let i = 0; i < len; i++) {
        const cur = buf[i];
        const t = T[4][OpCodes.And32(OpCodes.Xor32(T[3][cur], T[12][OpCodes.And32(rngA.next(), 0xFF)]), 0xFF)];
        buf[i] = T[5][OpCodes.And32(OpCodes.Xor32(t, T[13][fb]), 0xFF)];
        fb = cur;
      }

      return Array.from(buf);
    }
  }

  const algorithmInstance = new DarkCryptBBCAlgorithm();
  if (!AlgorithmFramework.Find(algorithmInstance.name)) {
    RegisterAlgorithm(algorithmInstance);
  }

  return { DarkCryptBBCAlgorithm, DarkCryptBBCInstance };
}));
